use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "open" {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(parts[1].clone()) {
                println("error: duplicate account")
            } else {
                acc.insert(parts[1].clone(), amt)
                println("ok")
            }
        } else if cmd == "balance" {
            if acc.contains_key(parts[1].clone()) {
                println("${acc[parts[1].clone()]}")
            } else {
                println("error: unknown account ${parts[1]}")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            let name = parts[1].clone()
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(name.clone()) {
                println("error: unknown account ${name}")
            } else {
                let bal = acc[name.clone()]
                if cmd == "deposit" {
                    acc.insert(name, bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(name, bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            let from = parts[1].clone()
            let to = parts[2].clone()
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(from.clone()) {
                println("error: unknown account ${from}")
            } else if !acc.contains_key(to.clone()) {
                println("error: unknown account ${to}")
            } else if from == to {
                println("error: same account")
            } else {
                let fb = acc[from.clone()]
                let tb = acc[to.clone()]
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(from, fb - amt)
                    acc.insert(to, tb + amt)
                    println("ok")
                }
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() {
        keys.push(k.clone())
    }
    keys.sort()
    for k in keys {
        println("${k} ${acc[k.clone()]}")
    }
}

